INSERT INTO public.admissions (admission_id, institution_id, college_id, program_id, admission_route, entrance_exam, admission_authority, eligibility, required_subjects, minimum_marks, other_requirements, application_url, academic_year, important_dates, source_id, verification_status, last_verified) VALUES (11, 2625, '00000000-0000-0004-0000-000000002625', 11, 'MAH-BCA/BBA/BMS/BBM CET 2026 followed by CAP 2026-27', 'MAH-BHMCT/BCA/BBA/BMS/BBM CET 2026', 'Commissioner, State CET Cell, Maharashtra', 'For the MAH-BCA/BBA/BMS/BBM CET: Indian national; passed 10+2 and eligible under the affiliating university Admission Policy. Final-year candidates may appear for the CET. Current CAP marks/subject rules for this institution/university are NOT VERIFIED in the cited 2026 CET brochure.', NULL, NULL, 'The 2026 CET brochure defers degree eligibility to the affiliating university policy and references prior-year CAP criteria; no current institution-specific marks or subjects inferred.', 'https://cetcell.mahacet.org/cap-_2026-27/', '2026-27', NULL, 401, 'VERIFIED', '2026-10-03') ON CONFLICT (admission_id) DO NOTHING;
INSERT INTO public.admissions (admission_id, institution_id, college_id, program_id, admission_route, entrance_exam, admission_authority, eligibility, required_subjects, minimum_marks, other_requirements, application_url, academic_year, important_dates, source_id, verification_status, last_verified) VALUES (12, 2625, '00000000-0000-0004-0000-000000002625', 12, 'MAH-BCA/BBA/BMS/BBM CET 2026 followed by CAP 2026-27', 'MAH-BHMCT/BCA/BBA/BMS/BBM CET 2026', 'Commissioner, State CET Cell, Maharashtra', 'For the MAH-BCA/BBA/BMS/BBM CET: Indian national; passed 10+2 and eligible under the affiliating university Admission Policy. Final-year candidates may appear for the CET. Current CAP marks/subject rules for this institution/university are NOT VERIFIED in the cited 2026 CET brochure.', NULL, NULL, 'The 2026 CET brochure defers degree eligibility to the affiliating university policy and references prior-year CAP criteria; no current institution-specific marks or subjects inferred.', 'https://cetcell.mahacet.org/cap-_2026-27/', '2026-27', NULL, 401, 'VERIFIED', '2026-10-03') ON CONFLICT (admission_id) DO NOTHING;
INSERT INTO public.admissions (admission_id, institution_id, college_id, program_id, admission_route, entrance_exam, admission_authority, eligibility, required_subjects, minimum_marks, other_requirements, application_url, academic_year, important_dates, source_id, verification_status, last_verified) VALUES (13, 2625, '00000000-0000-0004-0000-000000002625', 13, 'MAH-BHMCT/BCA/BBA/BMS/BBM CET 2026 or MHT-CET 2026 (PCM or PCB), followed by CAP 2026-27', 'MAH-BHMCT/BCA/BBA/BMS/BBM CET 2026; MHT-CET 2026 (PCM or PCB)', 'Commissioner, State CET Cell, Maharashtra', 'For the MAH-BCA/BBA/BMS/BBM CET: Indian national; passed 10+2 and eligible under the affiliating university Admission Policy. Final-year candidates may appear for the CET. Current CAP marks/subject rules for this institution/university are NOT VERIFIED in the cited 2026 CET brochure.', NULL, NULL, 'The 2026 CET brochure defers degree eligibility to the affiliating university policy and references prior-year CAP criteria; no current institution-specific marks or subjects inferred. CET Cell notice dated 20/07/2026 also allowed candidates who appeared for MHT-CET 2026 (PCM or PCB) to apply for BBA/BCA/BMS using that score; the notice listed 26/07/2026 as the registration deadline.', 'https://cetcell.mahacet.org/cap-_2026-27/', '2026-27', NULL, 401, 'VERIFIED', '2026-10-03') ON CONFLICT (admission_id) DO NOTHING;
