INSERT INTO public.scholarships (scholarship_id, institution_id, college_id, program_id, name, provider, eligibility, category, benefit, academic_year, application_url, source_id, source_url, verification_status, last_verified, notes) VALUES (1, NULL, NULL, NULL, 'Payment of Tuition Fees and Examination Fees to OBC Girls Pursuing Professional Courses', 'OBC, SEBC, VJNT & SBC Welfare Department, Government of Maharashtra', 'Applicant must be an OBC girl, Maharashtra resident, enrolled in a government-approved professional course, admitted to an eligible Government/Government Aided/Private Non-Aided/Permanently Non-Aided institution through a CAP round; renewal and progression conditions apply as stated on the official scheme page. Income threshold: UNKNOWN on this scheme page.', 'OBC; female applicants', '100% reimbursement of tuition fees and examination fees under GR dated 08-07-2024; reimbursement is fee-based and not a fixed cash amount.', NULL, 'https://mahadbt2.maharashtra.gov.in/', 419, 'https://mahadbt.maharashtra.gov.in/SchemeData/SchemeData?str=E9DDFA703C38E51A861D18FEEFAC4F5F6568CABC51F37B2D8E783259DE953673', 'VERIFIED', '2026-10-03', 'Statewide scheme. No institution/program foreign-key match is asserted. The detailed scheme page requires CAP admission; VU programs in this dataset have university-level admission routes and are not linked to this scheme. Detailed page does not label an academic year; MahaDBT portal announcement states AY 2026-27 applications use MahaDBT 2.0.') ON CONFLICT (scholarship_id) DO NOTHING;
